with exploded as (select id, service, host, log_ts, level, latency_ms, key, v from app_logs lateral view explode(context) x as key, v) select id, host, log_ts, level, key, v, first_value(key) ignore nulls over w_ordered as first_known_key, avg(latency_ms) over (partition by month(log_ts), level order by cast(log_ts as bigint) range between 1800 preceding and current row) as latency_ms_avg_30m, dense_rank() over (partition by key, service order by latency_ms desc nulls first) as latency_ms_dense_rank from exploded where level = 'INFO' window w_ordered as (partition by to_date(log_ts), level order by latency_ms, id, key rows between unbounded preceding and current row);
